# plots-export-ts.py : writes docs/city_plots_tiled.json into src/roads/debug/PlotData.ts (used by the key 5 plot layer). Run: python3 tools/plots-export-ts.py
import json
d = json.load(open('docs/city_plots_tiled.json')); rows = []
for p in d['plots']:
    flat = ','.join(f'{v:g}' for xz in p['poly'] for v in xz)
    rows.append(f"[{2 if p.get('access') else 1 if p['tiny'] else 0},{p['area']},{flat}]")
open('src/roads/debug/PlotData.ts', 'w').write(
    "// GENERATED by tools/plots-export-ts.py from docs/city_plots_tiled.json - do not edit. Each row: [flag (0 plot, 1 tiny leftover, 2 access road parcel), area m2, x0, z0, x1, z1, ...] one closed plot outline.\n"
    "export const PLOTS: number[][] = [\n" + ',\n'.join(rows) + '\n];\n')
print('plots', len(rows))
# garden trees inside plots (docs/city_plot_trees.json) -> src/vegetation/PlotTreeData.ts
T = json.load(open('docs/city_plot_trees.json'))
open('src/vegetation/PlotTreeData.ts', 'w').write(
    "// GENERATED by tools/plots-export-ts.py from docs/city_plot_trees.json - do not edit. Garden trees inside the city plots, game tree kinds only.\n"
    "// Flat list, 5 numbers per tree: x, z (world m), TreeKind, scale, yaw (rad).\n"
    "export const PLOT_TREES: number[] = [" + ','.join(f'{v:g}' for t in T for v in t) + '];\n')
print('plot trees', len(T))
